import{_ as r,o as n,c as t,ae as a}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Recherche: Die Causa „Postenschacher“ (August Wöginger)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/postenschacher-woeginger.md","filePath":"recherche/postenschacher-woeginger.md"}'),i={name:"recherche/postenschacher-woeginger.md"};function s(u,e,h,g,l,o){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="recherche-die-causa-„postenschacher-august-woginger" tabindex="-1">Recherche: Die Causa „Postenschacher“ (August Wöginger) <a class="header-anchor" href="#recherche-die-causa-„postenschacher-august-woginger" aria-label="Permalink to &quot;Recherche: Die Causa „Postenschacher“ (August Wöginger)&quot;">​</a></h1><p><strong>Der Fall des Klubobmanns: Wenn politische Intervention auf Amtsmissbrauch trifft.</strong></p><p>Parallel zu den historischen Machenschaften der Ära Horten bietet die aktuelle politische Landschaft Österreichs reichlich Stoff für unsere Mockumentary. Ein Paradebeispiel für moderne Interventionen ist der Prozess gegen ÖVP-Klubobmann <strong>August Wöginger</strong>, der sich aktuell (Stand Februar/März 2026) vor dem Landesgericht Linz verantworten muss.</p><hr><h2 id="der-vorwurf-bestimmung-zum-amtsmissbrauch" tabindex="-1">Der Vorwurf: Bestimmung zum Amtsmissbrauch <a class="header-anchor" href="#der-vorwurf-bestimmung-zum-amtsmissbrauch" aria-label="Permalink to &quot;Der Vorwurf: Bestimmung zum Amtsmissbrauch&quot;">​</a></h2><p>Die Wirtschafts- und Korruptionsstaatsanwaltschaft (WKStA) wirft August Wöginger vor, im Jahr 2017 bei <strong>Thomas Schmid</strong> (damals Generalsekretär im Finanzministerium) interveniert zu haben.</p><ul><li><strong>Das Ziel:</strong> Einem ÖVP-Bürgermeister aus dem Bezirk Schärding sollte der Posten als Leiter des Finanzamts Braunau-Ried-Schärding verschafft werden.</li><li><strong>Die Problematik:</strong> Eine andere Bewerberin, Christa Scharf, galt laut Bundesverwaltungsgericht als fachlich besser qualifiziert. Sie wurde jedoch übergangen.</li><li><strong>Die Rolle Wögingers:</strong> Er wird als „Bestimmungstäter“ geführt, da er die Entscheidungsträger zur unrechtmäßigen Besetzung angestiftet haben soll.</li></ul><hr><h2 id="aktueller-stand-der-gerichtsverhandlung-februar-2026" tabindex="-1">Aktueller Stand der Gerichtsverhandlung (Februar 2026) <a class="header-anchor" href="#aktueller-stand-der-gerichtsverhandlung-februar-2026" aria-label="Permalink to &quot;Aktueller Stand der Gerichtsverhandlung (Februar 2026)&quot;">​</a></h2><p>Nachdem eine ursprünglich geplante Diversion (Zahlung einer Geldbuße ohne Schuldeingeständnis) durch das Oberlandesgericht Linz aufgehoben wurde, läuft nun die Hauptverhandlung.</p><h3 id="_1-einvernahmen-der-mitangeklagten-26-27-februar-2026" tabindex="-1">1. Einvernahmen der Mitangeklagten (26./27. Februar 2026) <a class="header-anchor" href="#_1-einvernahmen-der-mitangeklagten-26-27-februar-2026" aria-label="Permalink to &quot;1. Einvernahmen der Mitangeklagten (26./27. Februar 2026)&quot;">​</a></h3><p>In den letzten zwei Tagen wurden die zwei mitangeklagten Finanzbeamten getrennt befragt:</p><ul><li><strong>Der Kommissionsvorsitzende (Siegfried M.):</strong> Bekennt sich „nicht schuldig“ und betont die Korrektheit des Hearings.</li><li><strong>Der Personalvertreter (Herbert B.):</strong> Gab zu, dass Thomas Schmid ihn gebeten habe, den Bürgermeister zu unterstützen („dass es der Bürgermeister werden soll“), bestreitet aber, die Bewertung manipuliert zu haben.</li></ul><h3 id="_2-der-nachste-termin-woginger-sagt-aus" tabindex="-1">2. Der nächste Termin: Wöginger sagt aus <a class="header-anchor" href="#_2-der-nachste-termin-woginger-sagt-aus" aria-label="Permalink to &quot;2. Der nächste Termin: Wöginger sagt aus&quot;">​</a></h3><ul><li><strong>3. März 2026:</strong> August Wöginger ist zur persönlichen Einvernahme geladen.</li><li><strong>Strafrahmen:</strong> Im Falle einer Verurteilung drohen sechs Monate bis zu fünf Jahre Haft.</li><li><strong>Politische Folgen:</strong> Wöginger hat bereits angekündigt, auch bei einem Schuldspruch erster Instanz nicht als Klubobmann zurückzutreten.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>In unserer Mockumentary ziehen wir Parallelen zwischen der historischen Begünstigung von „Freunden“ (wie Helmut Horten durch das NS-Regime) und dem modernen Postenschacher.</p><ul><li><strong>Das Motiv der „Intervention“:</strong> Es zeigt, dass Macht nicht nur durch Geld (Spenden), sondern auch durch den Zugriff auf staatliche Strukturen (Postenbesetzungen) gefestigt wird.</li><li><strong>Satirische Umsetzung:</strong> Wir planen eine Szene, in der ein fiktiver Politiker versucht, eine Intervention als „regionale Strukturförderung“ umzudeuten – ganz im Stil von Wögingers Verteidigungslinie.</li></ul><hr><p><em>Quellen: Aktuelle Berichterstattung (Trend, Krone, Kurier, OE24) vom 27. Februar 2026, Akten der WKStA.</em></p>',21)])])}const m=r(i,[["render",s]]);export{c as __pageData,m as default};
